def run(context):
    # Placeholder logic for demonstration
    add_candidates = []
    trim_candidates = []
    for record in context['scores.stage_snapshots']:
        if record['trend_signal'] > 0 and record['stage_score'] > 50:
            add_candidates.append(record['symbol'])
        elif record['trend_signal'] < 0 and record['stage_score'] < 50:
            trim_candidates.append(record['symbol'])
    return {'add_candidates': add_candidates, 'trim_candidates': trim_candidates}
